<?php
requirePermission('products');
$edit=query('SELECT * FROM products WHERE id=?',[(int)($_GET['id']??0)])->fetch()?:[];
$live=heroProducts();$heroCount=sliderConfig()['count'];$liveIds=array_map(fn($p)=>(int)$p['id'],$live);
$term='%'.mb_substr((string)($_GET['q']??''),0,100).'%';$placement=(string)($_GET['placement']??'');$category=(int)($_GET['category']??0);$where='(p.name LIKE ? OR p.sku LIKE ?)';$args=[$term,$term];
if($category){$where.=' AND p.category_id=?';$args[]=$category;}
$brand=brandsReady()?(int)($_GET['brand']??0):0;if($brand){$where.=' AND p.brand_id=?';$args[]=$brand;}
$where.=match($placement){'hero_live'=>$liveIds?' AND p.id IN ('.implode(',',$liveIds).')':' AND 1=0','hero'=>' AND p.hero_selected=1','home'=>' AND p.featured=1','inactive'=>' AND p.active=0','low'=>inventoryEnabled()?' AND p.stock<=p.low_stock_threshold':'',default=>''};
$number=max(1,min(10000,(int)($_GET['p']??1)));$offset=($number-1)*50;$count=(int)query("SELECT COUNT(*) FROM products p WHERE $where",$args)->fetchColumn();
$products=query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY p.id DESC LIMIT 50 OFFSET $offset",$args)->fetchAll();
?>
<div class="page-title"><div><p class="eyebrow">KATALOG I OBJAVLJIVANJE</p><h1>Proizvodi</h1><p>Objava, raspored na naslovnici i stanje svakog artikla.</p></div><a class="btn" href="?page=products&create=1#product-editor">＋ Novi artikal</a></div>
<section class="panel hero-monitor"><div class="section-heading"><div><h2>Trenutno u velikom naslovnom prikazu</h2><p>Posljednjih <?=$heroCount?> odabranih aktivnih artikala s oznakom "Velika naslovna objava".</p></div><a class="text-link" href="?page=products&placement=hero_live">Filtriraj ove artikle ↗</a></div><div class="hero-monitor-grid"><?php foreach($live as $i=>$p):?><a href="?page=products&id=<?=$p['id']?>#product-editor"><span class="slot-number">0<?=$i+1?></span><img src="<?=e(imageSource($p['image_url']))?>" alt=""><span><strong><?=e($p['name'])?></strong><small><?=e($p['sku'])?> · <?=money((float)$p['price'])?></small></span><b>↗</b></a><?php endforeach;for($i=count($live);$i<$heroCount;$i++):?><div class="empty-slot"><span class="slot-number">0<?=$i+1?></span><span>Slobodno mjesto<small>Označite artikal za veliki prikaz.</small></span></div><?php endfor;?></div></section>
<?php if($edit||isset($_GET['create'])||$error):?><section id="product-editor" class="panel editor-panel"><div class="section-heading"><h2><?=$edit?'Uredi artikal':'Novi artikal'?></h2><a href="?page=products">Zatvori ✕</a></div><?php startForm('product',(int)($edit['id']??0));?><div class="editor-grid"><div><?php field('name','Naziv artikla',$edit['name']??'');if($edit)field('sku','Broj artikla / postojeća šifra',$edit['sku']);else echo '<label>Broj artikla</label><input value="Dodjeljuje se automatski nakon spremanja" readonly><p class="field-help">Novi brojevi idu od 1 nadalje. Postojeće oznake ostaju sačuvane; zauzeti brojevi se preskaču.</p>';$options=[0=>'Bez kategorije'];foreach(query('SELECT * FROM categories ORDER BY sort_order,name')->fetchAll() as $c)$options[$c['id']]=$c['name'];selectField('category_id','Kategorija',$options,$edit['category_id']??0);if(brandsReady()){$brandOptions=[0=>'Bez brenda'];foreach(query('SELECT id,name,active FROM brands ORDER BY sort_order,name')->fetchAll() as $b)$brandOptions[$b['id']]=$b['name'].($b['active']?'':' (isključen)');selectField('brand_id','Brend / proizvođač',$brandOptions,$edit['brand_id']??0);}field('price','Prodajna cijena KM (npr. 29.90)',$edit['price']??'0.00');field('compare_price','Stara cijena za precrtavanje KM (prazno = bez akcije)',$edit['compare_price']??'','text',false);if(inventoryEnabled()&&can('inventory')){field('purchase_price','Trenutna nabavna cijena KM',$edit['purchase_price']??'0.00');field('low_stock_threshold','Prag upozorenja za nizak lager',$edit['low_stock_threshold']??3,'number');}textField('description','Detaljan opis i specifikacije',$edit['description']??'');?></div><div><?php field('image_url','Glavna slika — HTTPS ili postojeća lokalna adresa',$edit['image_url']??'','text',false);?><label for="image">Postavi novu glavnu sliku</label><input id="image" name="image" type="file" accept="image/jpeg,image/png,image/webp"><p class="field-help">JPG, PNG ili WebP · najviše 5 MB po slici.</p><?php $gallery=$edit?query('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order,id',[$edit['id']])->fetchAll(PDO::FETCH_COLUMN):[];textField('gallery_urls','Dodatne slike (jedna adresa po redu)',implode("\n",$gallery));?><label for="gallery">Dodaj slike u galeriju</label><input id="gallery" name="gallery[]" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="field-help">Prve dvije različite dodatne slike prikazuju se i kao detalji u velikoj naslovnoj objavi. Ukupno do osam dodatnih slika. Za uklanjanje izbrišite odgovarajuću adresu iz polja iznad.</p><?php field('hero_banner_url','Široki baner za naslovnicu — adresa slike',$edit['hero_banner_url']??'','text',false);?><label for="hero_banner">Postavi široki naslovni baner</label><input id="hero_banner" name="hero_banner" type="file" accept="image/jpeg,image/png,image/webp"><p class="field-help">Preporuka: 1920 × 680 px, JPG/PNG/WebP do 5 MB. Baner se prikazuje cijeli, bez rezanja. Za uklanjanje obrišite adresu. Bez banera koristi se automatski prikaz naziva, cijene i glavne slike artikla. Dugme „Pogledaj ponudu“ dodaje sistem.</p><fieldset class="publication-options"><legend>Gdje se artikal prikazuje?</legend><label><input type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>><span><strong>Objavljen u prodavnici</strong><small>Isključeno = skriven od kupaca.</small></span></label><label><input type="checkbox" name="featured" <?=!$edit||$edit['featured']?'checked':''?>><span><strong>Lista artikala na naslovnici</strong><small>Prikaz u običnom katalogu početne stranice.</small></span></label><label><input type="checkbox" name="hero_selected" <?=!empty($edit['hero_selected'])?'checked':''?>><span><strong>Velika naslovna objava</strong><small>Rotiraju se posljednji odabrani aktivni artikli; broj, trajanje i efekat uređuju se u Teme → Rotirajući prikaz.</small></span></label></fieldset><p class="field-help">Redoslijed određuje vrijeme odabira za slider. Uređivanje opisa ne pomjera objavu. Dugmetom „U naslovni slider“ ponovo je dodajte među posljednje. <?=inventoryEnabled()?'Količine mijenjajte kroz Lager.':'Praćenje lagera je isključeno.'?></p></div></div><div class="form-footer"><button>Spremi artikal</button><a href="?page=products">Odustani</a></div></form></section><?php endif;?>
<section class="panel"><form method="get" class="admin-filters"><input type="hidden" name="page" value="products"><div><?php field('q','Pretraži naziv ili SKU',$_GET['q']??'','text',false);?></div><div><?php selectField('placement','Prikaz',[''=>'Svi artikli','hero_live'=>'Trenutne objave u slideru','hero'=>'Svi označeni za veliki prikaz','home'=>'Lista na naslovnici','inactive'=>'Skriveni artikli',...(inventoryEnabled()?['low'=>'Nizak lager']:[])],$placement);?></div><div><?php $opts=[0=>'Sve kategorije'];foreach(query('SELECT * FROM categories ORDER BY name')->fetchAll() as $c)$opts[$c['id']]=$c['name'];selectField('category','Kategorija',$opts,$category);?></div><?php if($brand):?><input type="hidden" name="brand" value="<?=$brand?>"><?php endif;?><button>Primijeni filter</button></form><div class="table-heading"><h2>Registar artikala</h2><span><?=$count?> rezultata</span></div><div class="table-scroll"><table><thead><tr><th>Artikal / šifra</th><th>Kategorija</th><th>Prodajna cijena</th><?php if(inventoryEnabled()):?><th>Slobodno</th><th>Rezervisano</th><?php endif;?><th>Objava i naslovnica</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><a class="product-table-name" href="?page=products&id=<?=$p['id']?>#product-editor"><img src="<?=e(imageSource($p['image_url']))?>" alt=""><span><strong><?=e($p['name'])?></strong><small><?=e($p['sku'])?></small></span></a></td><td><?=e($p['category_name']??'—')?></td><td class="numeric"><?=money((float)$p['price'])?></td><?php if(inventoryEnabled()):?><td><span class="<?= (int)$p['stock']<=(int)$p['low_stock_threshold']?'stock-warning':''?>"><?=$p['stock']?></span></td><td><?=$p['reserved']?></td><?php endif;?><td><span class="status-badge <?=$p['active']?'status-completed':'status-cancelled'?>"><?=$p['active']?'Objavljen':'Skriven'?></span><?php if(in_array((int)$p['id'],$liveIds,true)):?><span class="status-badge status-new">Velika objava #<?=array_search((int)$p['id'],$liveIds,true)+1?></span><?php elseif($p['hero_selected']):?><span class="status-badge">Veliki prikaz: na čekanju</span><?php endif;if($p['featured']):?><small class="cell-note">Lista na naslovnici</small><?php endif;?></td><td><a class="table-action" href="?page=products&id=<?=$p['id']?>#product-editor">Uredi ↗</a><?php if(brandsReady()&&$p['active']):startForm('hero_publish',(int)$p['id']);?><button class="btn secondary">U naslovni slider</button></form><?php endif;?></td></tr><?php endforeach;if(!$products):?><tr><td colspan="7" class="table-empty">Nema artikala za odabrane filtere.</td></tr><?php endif;?></tbody></table></div><div class="list-pagination"><span>Stranica <?=$number?> / <?=max(1,(int)ceil($count/50))?></span><?php foreach([-1=>'← Prethodna',1=>'Sljedeća →'] as $delta=>$label):if(($delta<0&&$number>1)||($delta>0&&$offset+50<$count)):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$number+$delta])))?>"><?=$label?></a><?php endif;endforeach;?></div></section>
